(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18+Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.017-t*0.27)*18+Math.sin(x*0.016+t*0.33)*12;
  const w2x = Math.sin((x+y)*0.009+t*0.15)*25;
  const w2y = Math.cos((x-y)*0.011-t*0.18)*25;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.1],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.4],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.6],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.7],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 2.0],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*60, 0.07, 2.2],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75)*55, 0.095, 1.9]
  ];
  let aS=0, iS=0, hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.8+3.0);
  }
  const act=aS/8, inh=iS/8, inhb=hS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const ripple=Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.005)*0.3;
  const micro=(Math.sin(sx*0.25+t*1.5)*Math.sin(sy*0.25-t*1.2)+Math.sin((sx-sy)*0.2+t*0.8))*0.15;
  const reaction=Math.tanh((act-inh*0.6-inhb*0.2+bg*0.25+spiral+ripple+micro)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const warp=Math.sin(reaction*4+act)*0.15;
  const blend=reaction*0.65+cell*0.2+warp*0.15, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,95],[18,85,130],[25,140,145],
    [180,175,65],[215,135,60],[185,65,65],[120,30,55],
    [55,18,65],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,1-dist/280)*0.08*Math.sin(t*0.5+ang*2);
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*50)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
